'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const rp=n=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(n||0);
const date=s=>s?new Date(s).toLocaleString('id-ID',{timeZone:'Asia/Jakarta',dateStyle:'medium',timeStyle:'short'}):'Belum dijadwalkan';
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',bag:'M5 7h14l1 14H4L5 7z M8 8V6a4 4 0 0 1 8 0v2',box:'m3 7 9-5 9 5-9 5-9-5v10l9 5 9-5V7 M12 12v10 M7 4l10 6',chart:'M4 3v17h17 M7 14l4-5 4 3 5-8',live:'M3 5h13v14H3z m13 5 5-3v10l-5-3',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3z',users:'M16 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2 M17 4a4 4 0 0 1 0 8 M23 21v-2a4 4 0 0 0-3-3.9 M12 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',target:'M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20 M12 6a6 6 0 1 0 0 12 6 6 0 0 0 0-12 M12 10a2 2 0 1 0 0 4 2 2 0 0 0 0-4',wallet:'M3 5h17v15H3z M3 5V3h14v2 M15 10h7v6h-7z M18 13h1',settings:'M4 6h16 M4 12h16 M4 18h16 M8 3v6 M16 9v6 M9 15v6',search:'M21 21l-6-6 M17 9A7 7 0 1 1 3 9a7 7 0 0 1 14 0',plus:'M12 5v14 M5 12h14',arrow:'M5 12h14 M14 7l5 5-5 5',alert:'m12 3 10 18H2L12 3z M12 9v5 M12 17h.01',check:'M5 12l4 4L20 5',menu:'M4 6h16 M4 12h16 M4 18h16',close:'M6 6l12 12 M18 6 6 18',logout:'M9 3H3v18h6 M9 12h13 M17 7l5 5-5 5',shirt:'m8 3-6 4 3 5 3-2v11h8V10l3 2 3-5-6-4c-1 3-7 3-8 0',clock:'M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20 M12 6v6l4 2',link:'m10 13 4-4 M8 16l-2 2a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0 M16 8l2-2a4 4 0 0 1 6 6l-5 5a4 4 0 0 1-6 0'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.grid}"/></svg>`;
const button=(label,action,id='',cls='')=>`<button type="button" class="${cls}" data-action="${action}" data-id="${esc(id)}" ${!label.replace(/<[^>]*>/g,'').trim()?`aria-label="${esc(({menu:'Buka menu',refresh:'Muat ulang data',close:'Tutup',logout:'Keluar',print:'Cetak bukti','cart-remove':'Hapus dari keranjang','task-toggle':'Ubah status tugas'})[action]||action)}"`:''}>${label}</button>`;
const tag=(s,kind='')=>`<span class="tag ${kind}">${esc(s)}</span>`;
const logo=()=>'<a class="brand brandasset" href="#dashboard" aria-label="Albina Shop"><img src="/assets/albina-shop-logo-hd.jpg" alt="Albina Shop"></a>';
const users=[{id:'owner',name:'Owner',role:'owner'},{id:'admin',name:'Upi',role:'admin'},{id:'host1',name:'Feby',role:'host'},{id:'host2',name:'Tantri',role:'host'},{id:'host3',name:'Bowo',role:'host'}];
const sampleProducts=[['Kaos Sporty Dewasa','Olive · M',24,85000],['Dress Brukat Anak','Cream · 6 tahun',3,125000],['Kaos Crop Anak','Peach · S',35,55000],['Celana Chinos Dewasa','Sand · L',1,115000],['Setelan Katun Anak','Sage · 8 tahun',18,95000]].map((p,i)=>({id:'sample'+i,sku:'CONTOH-'+(i+1),name:p[0],variant:p[1],stock:p[2],reserved:0,quarantine:0,price:p[3],threshold:5}));
let S=null,preview=false,page='dashboard',range='30',channel='Semua channel',cart=[],formHandler=null;
let chatOpen=false,chatBusy=false,chatUser='',chatMessages=[];
let submitOperation='',toastTimer;
const operational=()=>S?.user.role!=='host', owner=()=>S?.user.role==='owner';
const avail=p=>p.stock-p.reserved-p.quarantine;
const pending=()=>S.syncTasks.filter(x=>x.status==='Menunggu');
const who=id=>S.users.find(u=>u.id===id)?.name||id;
const options=(values,selected='')=>values.map(v=>{const [id,label]=Array.isArray(v)?v:[v,v];return `<option value="${esc(id)}" ${id===selected?'selected':''}>${esc(label)}</option>`}).join('');
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',4500)}
async function api(path,body){let response;try{response=await fetch('/api/'+path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json','X-CSRF':S?.user.csrf||''}:{},body:body?JSON.stringify(body):undefined})}catch{throw new Error('Koneksi terputus. Hasil penyimpanan belum diketahui; periksa riwayat sebelum mengulang.')}const data=await response.json();if(!response.ok){const error=new Error(data.error||'Permintaan gagal.');error.status=response.status;throw error}return data}
async function refresh(){S=await api('state');preview=false;render()}
async function boot(){try{let status=await api('status');if(status.setup){preview=true;S={user:{id:'owner',name:'Owner',role:'owner'},demo:true,users,products:sampleProducts,orders:[],tasks:[{id:'p1',title:'Cocokkan stok dengan BigSeller dan fisik gudang',assignee:'admin',status:'Belum mulai',due:''},{id:'p2',title:'Siapkan produk untuk live',assignee:'host1',status:'Belum mulai',due:''},{id:'p3',title:'Tinjau koleksi dewasa',assignee:'host2',status:'Belum mulai',due:''}],live:[],campaigns:[],expenses:[],approvals:[],movements:[],audit:[],syncTasks:[],baseline:null,baselineScope:'',startDate:''};render()}else{try{await refresh()}catch(e){if(e.status===401)login();else throw e}}}catch(e){$('#app').innerHTML=`<section class="auth card"><h1>Workspace belum dapat dimuat</h1><p>${esc(e.message)}</p>${button('Coba lagi','reload')}</section>`}}
function login(){S=null;$('#app').innerHTML=`<section class="auth card">${logo()}<p class="eyebrow">ALBINA WORKSPACE</p><h1>Selamat datang kembali.</h1><p class="muted">Masuk untuk melanjutkan pekerjaan tim.</p><form id="loginform"><label>Akun<select name="id">${options(users.map(u=>[u.id,(u.role==='host'?'Host ':u.role==='admin'?'Admin ':'')+u.name]))}</select></label><label>Password<input type="password" name="password" required autocomplete="current-password"></label><div class="error" role="alert"></div><button class="primary" type="submit">Masuk ke workspace ${icon('arrow')}</button></form><p class="muted">Akun Upi, Feby, Tantri dan Bowo diaktifkan owner melalui menu Tim.</p></section>`;$('#loginform').onsubmit=async e=>{e.preventDefault();const f=e.target,b=f.querySelector('button');b.disabled=true;try{await api('login',Object.fromEntries(new FormData(f)));await refresh()}catch(err){f.querySelector('.error').textContent=err.message;f.querySelector('.error').classList.add('show')}finally{b.disabled=false}}}
const menus=[['dashboard','Ringkasan','grid'],['pos','POS Offline','bag'],['inventory','Stok & Gudang','box'],['orders','Riwayat Transaksi','chart'],['live','Live Selling','live'],['marketing','Marketing','spark'],['team','Tim & Pekerjaan','users'],['okr','Target & OKR','target'],['finance','Keuangan','wallet'],['assistant','Albina Assistant','spark'],['settings','Integrasi & Pengaturan','settings']];
function allowed(k){return operational()||!['pos','orders','finance','settings','marketing'].includes(k)}
function render(){page=location.hash.slice(1)||'dashboard';if(!menus.some(m=>m[0]===page)||!allowed(page))page='dashboard';const m=menus.find(m=>m[0]===page);$('#app').innerHTML=`<aside class="sidebar">${logo()}<div class="workspace"><span class="letter">A</span><div><strong>Albina Workspace</strong><small>Satu gudang. Satu tim.</small></div></div><nav>${menus.filter(m=>allowed(m[0])).map((n,i)=>`${i===0?'<div class="navlabel">OPERASIONAL</div>':n[0]==='live'?'<div class="navlabel">TIM & PERTUMBUHAN</div>':n[0]==='finance'?'<div class="navlabel">ANALISIS & SISTEM</div>':''}<a href="#${n[0]}" class="navlink ${page===n[0]?'active':''}" ${page===n[0]?'aria-current="page"':''}>${icon(n[2])}${n[1]}${n[0]==='settings'&&pending().length?`<span class="navbadge">${pending().length}</span>`:''}</a>`).join('')}</nav><div class="sidefoot"><div class="localstatus"><span class="dot"></span> LOCAL WORKSPACE</div><p>BigSeller sebagai acuan stok.<br>Koneksi otomatis belum aktif.</p><div class="account"><span class="avatar">${esc(S.user.name.slice(0,2).toUpperCase())}</span><div><strong>${esc(S.user.name)}</strong><small>${esc(S.user.role)}</small></div>${!preview?button(icon('logout'),'logout','','iconbutton'):''}</div></div></aside><div class="shell"><header class="topbar"><div class="crumb">${button(icon('menu'),'menu','','iconbutton mobiletoggle')}<span>Workspace /</span><b>${m[1]}</b></div><div class="topright"><span class="statusbadge"><span class="dot"></span> TERSIMPAN LOKAL</span>${S.demo?'<span class="datachip">DATA CONTOH</span>':''}<span class="divider"></span>${button(icon('clock'),'refresh','','iconbutton')}<span class="avatar">${esc(S.user.name.slice(0,2).toUpperCase())}</span></div></header><main>${preview?`<div class="banner">${icon('spark')}<div><strong>Kenalan dengan workspace baru Albina.</strong><small>Ini pratinjau. Aktifkan akun owner untuk mulai mencatat di database lokal.</small></div>${button('Aktifkan workspace','setup','','primary')}</div>`:S.demo?'<div class="banner"><span class="dot"></span> Dataset contoh aktif. Transaksi tersimpan dalam database lokal contoh.</div>':''}${views[page]()}</main><footer><span>ALBINA SHOP · BUSINESS WORKSPACE</span><span>1 OWNER · 3 HOST · 1 ADMIN</span></footer><nav class="bottomnav">${(operational()?['dashboard','pos','inventory','team']:['dashboard','live','inventory','team']).map(k=>{const n=menus.find(x=>x[0]===k);return `<a href="#${k}" class="${page===k?'active':''}">${icon(n[2])}${n[1]}</a>`}).join('')}</nav></div>`;if($('#saleform'))initSale()}
function head(title,desc,actions=''){return `<div class="pagehead"><div><p class="eyebrow">ALBINA SHOP / ${page==='dashboard'?'BUSINESS OVERVIEW':esc(menus.find(m=>m[0]===page)?.[1])}</p><h1>${title}</h1><p class="muted">${desc}</p></div><div class="headtools">${actions}</div></div>`}
const filters=()=>`<div class="filters"><select id="range" aria-label="Periode laporan">${options([['1','Hari ini'],['7','7 hari terakhir'],['30','30 hari terakhir'],['all','Semua periode']],range)}</select><select id="channel" aria-label="Channel laporan">${options(['Semua channel','Toko langsung','WhatsApp','Reseller'],channel)}</select><span class="muted">Penjualan lunas berdasarkan tanggal transaksi · WIB</span></div>`;
function filtered(){let start=new Date();if(range==='1'){const parts=new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Jakarta'}).format(start);start=new Date(parts+'T00:00:00+07:00')}else start=new Date(Date.now()-Number(range)*86400000);return S.orders.filter(o=>(range==='all'||new Date(o.created)>=start)&&(channel==='Semua channel'||o.channel===channel))}
const totalSales=orders=>orders.reduce((a,o)=>a+o.paid,0);
function stat(label,value,desc,i='chart',kind=''){return `<section class="card stat"><div class="stathead"><span>${label}</span>${icon(i)}</div><div class="statvalue ${kind}">${value}</div><div class="statfoot">${desc}</div></section>`}
function empty(title,desc='',action=''){return `<div class="empty">${icon('box')}<strong>${title}</strong>${desc?`<p>${desc}</p>`:''}${action}</div>`}
function section(title,body,link='',cls=''){return `<section class="card ${cls}"><div class="sectionhead"><h2>${title}</h2>${link}</div>${body}</section>`}
function tasks(list=S.tasks){return list.length?list.map(t=>`<div class="taskrow ${t.status==='Selesai'?'done':''}">${button(t.status==='Selesai'?'✓':'','task-toggle',t.id)}<div><strong>${esc(t.title)}</strong><small>${esc(who(t.assignee))} · ${esc(t.status)}${t.due?' · '+esc(t.due):''}</small></div><span class="person">${esc(who(t.assignee).slice(0,2))}</span></div>`).join(''):empty('Belum ada pekerjaan','Tugas yang ditugaskan akan muncul di sini.')}
function targetBody(){return [1,3].map((month,i)=>`<div class="goaltitle"><span>Bulan ${month===1?'pertama':'ketiga'}</span><strong>${i===0?'3':'5'}×</strong></div><div class="progress ${i?'blue':''}"><span style="width:0%"></span></div><div class="split muted"><span>${S.baseline?rp(S.baseline*(i===0?3:5)):'Baseline belum ditetapkan'}</span><span>${i?'5':'3'}× baseline</span></div>`).join('')+`<div class="note">Kedua target memakai baseline yang sama. Progres aktual belum dihitung karena penjualan BigSeller belum terhubung.</div><div class="targetfooter"><span>Owner: Owner Albina</span><a href="#okr">Lihat OKR →</a></div>`}
function chart(orders){const days=Array.from({length:7},(_,i)=>new Date(Date.now()-(6-i)*86400000));const fmt=d=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Jakarta'}).format(d);const vals=days.map(d=>totalSales(orders.filter(o=>fmt(new Date(o.created))===fmt(d))));const max=Math.max(...vals,100000);const points=vals.map((v,i)=>`${35+i*85},${170-v/max*140}`).join(' ');return `<div class="chartsummary"><div><strong>${rp(vals.reduce((a,v)=>a+v,0))}</strong><span>Penjualan offline lunas · 7 hari</span></div></div><svg class="chart" viewBox="0 0 580 195" role="img" aria-label="Grafik penjualan offline tujuh hari"><defs><linearGradient id="area" x2="0" y2="1"><stop stop-color="#c2410c" stop-opacity=".22"/><stop offset="1" stop-color="#c2410c" stop-opacity="0"/></linearGradient></defs>${[30,77,123,170].map(y=>`<path d="M35 ${y}H560" stroke="currentColor" opacity=".12" stroke-dasharray="3 5"/>`).join('')}<polygon points="35,180 ${points} 545,180" fill="url(#area)"/><polyline points="${points}" fill="none" stroke="#c2410c" stroke-width="2.7"/>${vals.map((v,i)=>`<circle cx="${35+i*85}" cy="${170-v/max*140}" r="3" fill="#c2410c"/>`).join('')}<text x="0" y="32" class="charttext">${max>=1000000?(max/1000000).toFixed(1)+' jt':Math.round(max/1000)+' rb'}</text><text x="10" y="173" class="charttext">0</text></svg><div class="chartlabels">${days.map(d=>`<span>${new Intl.DateTimeFormat('id-ID',{timeZone:'Asia/Jakarta',weekday:'short'}).format(d)}</span>`).join('')}</div>`}
function stockTable(products=S.products,compact=false){return products.length?`<div class="tablewrap"><table><thead><tr><th>PRODUK / VARIAN</th>${compact?'':'<th class="right">FISIK</th><th class="right">TERPESAN</th><th class="right">KARANTINA</th>'}<th class="right">TERSEDIA</th><th>STATUS</th>${operational()?'<th></th>':''}</tr></thead><tbody>${products.map((p,i)=>`<tr data-search="${esc((p.name+' '+p.sku+' '+p.variant).toLowerCase())}"><td><div class="product"><span class="swatch">${icon('shirt')}</span><div><strong>${esc(p.name)}</strong><small>${esc(p.variant)} · <span class="mono">${esc(p.sku)}</span></small></div></div></td>${compact?'':`<td class="right number">${p.stock}</td><td class="right number">${p.reserved}</td><td class="right number">${p.quarantine}</td>`}<td class="right number ${avail(p)<=0?'negative':avail(p)<=p.threshold?'warning':''}">${avail(p)} <small>pcs</small></td><td>${tag(avail(p)<0?'Defisit':avail(p)===0?'Habis':avail(p)<=p.threshold?'Menipis':'Tersedia',avail(p)<=0?'bad':avail(p)<=p.threshold?'warn':'good')}</td>${operational()?`<td>${button('Detail','stock-detail',p.id,'smallbtn ghost')}</td>`:''}</tr>`).join('')}</tbody></table></div>`:empty('Belum ada produk','Tambahkan SKU dari katalog BigSeller dan saldo fisik yang sesuai.')}
function dashboard(){const orders=filtered(), low=S.products.filter(p=>avail(p)<=p.threshold);return head(`Selamat ${new Date().getHours()<12?'pagi':'datang'}, ${esc(S.user.name)} <span class="greeting">✿</span>`,'Review performa penjualan, stok, target, dan prioritas tim Albina.')+filters()+`<div class="dashboard-layout ${operational()?'with-sales':''}"><div class="dashboard-review"><div class="stats">${stat('Penjualan offline lunas',rp(totalSales(orders)),'<span class="dot positive"></span> Tersimpan di database lokal','bag')}${stat('Transaksi',orders.length,'Order unik · sesuai filter','chart')}${stat('Stok tersedia',S.products.reduce((a,p)=>a+avail(p),0)+' <small>pcs</small>','Salinan lokal · satu gudang','box')}${stat('SKU perlu perhatian',low.length+' <small>SKU</small>','Stok menipis, habis atau defisit','alert',low.length?'warn':'')}</div>${pending().length?`<div class="banner warn">${icon('alert')}<div><strong>${pending().length} perubahan perlu diperbarui di BigSeller</strong><small>Stok lokal berubah. Stok marketplace belum terkonfirmasi.</small></div><a href="#settings">Periksa →</a></div>`:''}<div class="two">${section(icon('chart')+' Performa penjualan',chart(orders),'<span class="legend"><span><span class="dot" style="color:#c2410c"></span> Offline lunas</span></span>')}${section(icon('target')+' Target pertumbuhan',targetBody(),tag('1 bulan · 3 bulan','info'))}</div><div class="two">${section(icon('box')+' Stok perlu perhatian',stockTable(low,true),'<a href="#inventory">Semua stok →</a>')}${section(icon('users')+' Prioritas tim',tasks(S.tasks.slice(0,4)),tag(S.tasks.filter(t=>t.status==='Selesai').length+'/'+S.tasks.length))}</div><div class="two">${section('Aktivitas terbaru',S.audit.length?S.audit.slice(0,4).map(a=>`<div class="activity"><span class="dot"></span><div>${esc(a.action)}<small>${esc(who(a.actor))} · ${date(a.created)}</small></div></div>`).join(''):empty('Workspace siap untuk langkah pertama','Mulai catat penjualan offline dan cocokkan saldo BigSeller.'))}${section('Mulai dari stok yang sehat.',`<p class="eyebrow">ALBINA ASSISTANT</p><p>${low.length} SKU membutuhkan perhatian. Cocokkan saldo lokal dengan BigSeller dan kondisi fisik sebelum menawarkan produk.</p>${button('Lihat insight stok '+icon('arrow'),'go-assistant')}`,'','ai-card')}</div></div>${offlineSales()}</div>`}
function ordersView(){if(page==='pos')return head('POS Penjualan Offline','Tools tambahan untuk mencatat transaksi lunas dari gudang bersama.')+offlineSales();return head('Riwayat Transaksi','Pembayaran lunas, barang diserahkan, stok lokal berkurang dalam satu transaksi.',button(icon('plus')+' Penjualan baru','sale','','primary')+button('Ekspor CSV','export-orders'))+filters()+section('Transaksi offline',filtered().length?`<div class="tablewrap"><table><thead><tr><th>TRANSAKSI</th><th>PEMBELI / CHANNEL</th><th>TOTAL</th><th>PEMBAYARAN</th><th>STATUS</th><th>PETUGAS</th><th></th></tr></thead><tbody>${filtered().map(o=>`<tr><td><span class="mono">${esc(o.id)}</span><div class="muted">${date(o.created)}</div></td><td>${esc(o.customer||'Pembeli umum')}<div class="muted">${esc(o.channel)}</div></td><td class="number nowrap">${rp(o.total)}</td><td>${tag(o.paid===o.total?'Lunas':'Belum lunas',o.paid===o.total?'good':'warn')}<div class="muted">${esc(o.method)}</div></td><td>${tag(o.status)}${o.refundable>o.refunded?'<div class="muted warning">Perlu refund</div>':''}</td><td>${esc(who(o.actor))}</td><td>${button('Detail','order',o.id,'smallbtn')}</td></tr>`).join('')}</tbody></table></div>`:empty('Belum ada transaksi','Transaksi akan muncul setelah penjualan berhasil tersimpan.',button('Catat penjualan pertama','sale','','primary')))}
function inventory(){return head('Stok & Gudang','Satu gudang untuk online dan offline. BigSeller tetap menjadi acuan stok.',operational()?button(icon('plus')+' Tambah SKU','product','','primary'):'')+`<div class="banner">${icon('link')}<div><strong>Saldo lokal belum terhubung otomatis ke BigSeller.</strong><small>Masukkan saldo awal dari BigSeller dan hasil hitung fisik. Setiap mutasi perlu rekonsiliasi.</small></div></div>`+section('Katalog & ketersediaan',`<div class="toolbar"><div class="search">${icon('search')}<input id="product-search" placeholder="Cari nama, SKU, ukuran atau warna…" aria-label="Cari produk"></div></div>${stockTable()}`)+ (operational()?section('Riwayat mutasi',S.movements.length?`<div class="tablewrap"><table><thead><tr><th>WAKTU</th><th>SKU</th><th>JENIS</th><th>FISIK</th><th>RESERVASI</th><th>PETUGAS / ALASAN</th></tr></thead><tbody>${S.movements.slice(0,50).map(m=>`<tr><td class="muted">${date(m.created)}</td><td class="mono">${esc(m.sku)}</td><td>${esc(m.kind)}</td><td class="number">${m.delta>0?'+':''}${m.delta}</td><td class="number">${m.reserved_delta}</td><td>${esc(who(m.actor))}<div class="muted">${esc(m.reason)}</div></td></tr>`).join('')}</tbody></table></div>`:empty('Belum ada mutasi')):'')}
function team(){return head('Tim & Pekerjaan','1 owner · Admin Upi · Host Feby, Tantri dan Bowo. Total 5 orang.',operational()?button(icon('plus')+' Tambah tugas','task','','primary'):'')+`<div class="teamgrid">${S.users.map(u=>`<section class="card teamcard"><span class="avatar">${esc(u.name.slice(0,2))}</span><h3>${esc(u.name)}</h3><div class="eyebrow">${esc(u.role)}</div>${tag(u.active?'Akun aktif':'Belum diaktifkan',u.active?'good':'warn')}${owner()?button('Atur akses login','password',u.id,'ghost'):''}</section>`).join('')}</div>`+section('Pekerjaan tim',tasks())+(operational()?section('Persetujuan owner',S.approvals.length?S.approvals.slice().reverse().map(a=>`<div class="connection"><div><strong>${esc(a.action)}</strong><p>Pengaju: ${esc(who(a.actor))} · ${date(a.created)}</p><p>${esc(JSON.parse(a.payload).reason||'')}</p>${tag(a.status,a.status==='Menunggu'?'warn':'')}</div>${owner()&&a.status==='Menunggu'?`<div class="rowactions">${button('Setujui','approve',a.id,'smallbtn primary')}${button('Tolak','reject',a.id,'smallbtn')}</div>`:''}</div>`).join(''):empty('Tidak ada persetujuan menunggu')):'')}
function live(){return head('Live Selling','Tiga host, satu gudang bersama. Jadwal dan hasil sesi dicatat manual.',operational()?button(icon('plus')+' Jadwal live','live','','primary'):'')+`<div class="three">${S.users.filter(u=>u.role==='host').map(u=>section(esc(u.name),`<p class="muted">${S.live.filter(l=>l.host===u.id).length} sesi terjadwal</p><div class="note">Produk sesi tidak membuat reservasi stok. Cek ketersediaan sebelum live.</div>`,tag('Host'))).join('')}</div>`+section('Jadwal & hasil sesi',S.live.length?S.live.map(l=>`<article class="session"><div class="sessionhead"><div><h3>${esc(l.title)}</h3><p>${esc(who(l.host))} · ${date(l.start)} — ${date(l.end)}</p></div>${tag(l.status,l.status==='Selesai'?'good':'')}</div><p>${esc(l.products||'Daftar produk belum diisi')}</p><div class="bottom"><span class="muted">${l.views===null?'Hasil belum dicatat':`${l.views} views · ${l.orders_count} order · ${rp(l.revenue)} (manual)`}</span>${button('Catat hasil','live-result',l.id,'smallbtn')}</div></article>`).join(''):empty('Belum ada jadwal live','Jadwalkan sesi Feby, Tantri atau Bowo.'))}
function marketing(){return head('Marketing','Rencanakan campaign dan catat biaya aktual. Atribusi marketplace belum terhubung.',owner()?button(icon('plus')+' Campaign baru','campaign','','primary'):'')+`<div class="three">${stat('Campaign',S.campaigns.length,'Dicatat di workspace','spark')}${stat('Biaya aktual',rp(S.campaigns.reduce((a,c)=>a+c.cost,0)),'Input manual owner','wallet')}${stat('ROAS','—','Data atribusi belum terhubung','chart')}</div>`+section('Rencana campaign',S.campaigns.length?S.campaigns.map(c=>`<div class="connection"><div><h3>${esc(c.title)}</h3><p>${esc(c.channel)} · anggaran ${rp(c.budget)} · aktual ${rp(c.cost)}</p></div>${tag(c.status)}</div>`).join(''):empty('Belum ada campaign','Anggaran dan pengeluaran aktual dicatat terpisah.'))}
function okr(){return head('Target & OKR','Bulan pertama 3× baseline. Bulan ketiga 5× baseline yang sama.',owner()?button('Tetapkan baseline','baseline','','primary'):'')+`<div class="two">${section('Target pertumbuhan Albina',targetBody(),tag('Target ditetapkan','info'))}${section('Parameter pengukuran',`<div class="kv"><span>Baseline</span><strong class="number">${S.baseline?rp(S.baseline):'Belum ditetapkan'}</strong></div><div class="kv"><span>Mulai pengukuran</span><strong>${esc(S.startDate||'Belum ditetapkan')}</strong></div><p class="muted">${esc(S.baselineScope||'Cakupan penjualan dan periode baseline perlu divalidasi.')}</p><div class="note">Target memakai baseline yang sama, bukan 3× lalu dikalikan lagi 5×. Data penjualan lokal tidak dianggap total omzet seluruh channel.</div>`)}</div>`+section('Prioritas pendukung',`<div class="connection"><div><h3>Seluruh penjualan offline tercatat</h3><p>PIC: Owner & Upi · transaksi lunas sebelum barang diserahkan.</p></div>${tag('Operasional')}</div><div class="connection"><div><h3>Stok lokal dan BigSeller cocok</h3><p>Verifikasi mutasi dan selisih sebelum menambah penjualan.</p></div>${tag(pending().length+' menunggu',pending().length?'warn':'good')}</div><div class="connection"><div><h3>Persiapan live konsisten</h3><p>Feby, Tantri, Bowo · produk, ketersediaan, jadwal, hasil sesi.</p></div>${tag('3 host')}</div>`)}
function finance(){const orders=filtered(),cash=orders.reduce((a,o)=>a+o.paid,0),refunds=orders.reduce((a,o)=>a+o.refunded,0);return head('Keuangan','Penerimaan transaksi lokal, refund dan pengeluaran. Belum laporan akuntansi lengkap.',owner()?button(icon('plus')+' Pengeluaran','expense','','primary'):'')+filters()+`<div class="three">${stat('Penerimaan tercatat',rp(cash),'Sesuai transaksi pada filter','wallet')}${stat('Refund tercatat',rp(refunds),'Catatan manual, bukan transfer bank','chart')}${stat('Penerimaan setelah refund',rp(cash-refunds),'Bukan laba bersih','chart')}</div><div class="two">${section('Penerimaan per metode',['Tunai','Transfer bank','QRIS'].map(m=>`<div class="connection"><span>${m}</span><strong class="number">${rp(orders.filter(o=>o.method===m).reduce((a,o)=>a+o.paid,0))}</strong></div>`).join(''))}${section('Kelengkapan laporan',`<p class="muted">Pembayaran marketplace, pencairan, biaya platform dan metode valuasi HPP belum terhubung. Tidak ada laba bersih yang dihitung dari data yang belum lengkap.</p>${owner()?`<div class="note">Pengeluaran lokal tercatat: ${rp(S.expenses.reduce((a,e)=>a+e.amount,0))}</div>`:''}`)}</div>`+(owner()?section('Pengeluaran',S.expenses.length?S.expenses.slice().reverse().map(e=>`<div class="connection"><div><strong>${esc(e.title)}</strong><p>${esc(e.category)} · ${date(e.created)}</p></div><span class="number">${rp(e.amount)}</span></div>`).join(''):empty('Belum ada pengeluaran dicatat')):'')}
function assistant(){const low=S.products.filter(p=>avail(p)<=p.threshold);return head('Albina Assistant','Insight lokal berbasis aturan. Belum agent AI atau koneksi data BigSeller.')+section('Briefing stok & aktivitas',`<div class="insight">${icon('box')}<div><h3>${low.length} SKU membutuhkan perhatian</h3><p>${esc(low.map(p=>p.name+' ('+avail(p)+' pcs)').join(', ')||'Semua SKU lokal berada di atas ambang peringatan.')}</p><p>Sumber: saldo fisik − karantina − reservasi pada database lokal.</p></div></div><div class="insight">${icon('link')}<div><h3>${pending().length} mutasi perlu verifikasi BigSeller</h3><p>Pembaruan lokal tidak otomatis mengubah stok marketplace. Tinjau antrean dan bukti pembaruan sebelum menandai cocok.</p></div></div><div class="insight">${icon('users')}<div><h3>${S.tasks.filter(t=>t.status!=='Selesai').length} tugas belum selesai</h3><p>Tim tetap: Owner, Upi, Feby, Tantri, Bowo. Buka halaman tim untuk tindak lanjut.</p></div></div>`)}
function settings(){return head('Integrasi & Pengaturan','BigSeller adalah master stok. Status koneksi dan verifikasi ditampilkan terpisah.')+section('Koneksi BigSeller',`<div class="connection"><div><h3>BigSeller Open API / MCP</h3><p>APP ID dan APP KEY diterbitkan BigSeller. Login web BigSeller saja tidak memberi akses API.</p></div>${tag(S.bigseller?.connected?'MCP terverifikasi':'Belum terhubung',S.bigseller?.connected?'good':'warn')}</div><p class="muted">${esc(S.bigseller?.message||'Koneksi belum dikonfigurasi. Cakupan tulis stok memerlukan dokumentasi/izin khusus; tidak diasumsikan tersedia melalui MCP.')}</p><div class="rowactions" style="margin-top:16px">${owner()?button('Hubungkan BigSeller MCP','connect-bigseller','','primary'):''}<a class="tag" href="https://www.bigseller.com/" target="_blank" rel="noreferrer">Buka BigSeller ↗</a><a class="tag" href="https://help.bigseller.com/in/detailPage/panduan-penggunaan-bigseller-mcp.9417" target="_blank" rel="noreferrer">Panduan resmi ↗</a></div>`)+section('Antrean pembaruan stok BigSeller',`<div class="sectionhead"><p class="muted">Verifikasi manual bukan pengiriman otomatis. Catat referensi penyesuaian dari BigSeller.</p>${button('Ekspor mutasi CSV','export-sync','','smallbtn')}</div>${S.syncTasks.length?S.syncTasks.slice().reverse().map(t=>`<div class="connection"><div><strong>${esc(t.reference)}</strong><p>${esc(t.action)} · ${date(t.created)}</p>${t.evidence?`<p>Bukti: ${esc(t.evidence)}</p>`:''}</div><div>${tag(t.status,t.status==='Menunggu'?'warn':'good')}${owner()&&t.status==='Menunggu'?button('Catat verifikasi','sync-confirm',t.id,'smallbtn'):''}</div></div>`).join(''):empty('Belum ada mutasi menunggu')}`)+section('Database & akun',`<div class="connection"><div><h3>SQLite lokal</h3><p>Data tersimpan di komputer ini, bukan di browser. Akses server hanya melalui localhost.</p></div>${tag('Database bersama','good')}</div><p class="muted">Backup: hentikan server, lalu salin seluruh folder albina-local/data sebelum dipindahkan atau diperbarui. Akun individual dikelola di menu Tim. Jangan membuka server ini ke internet.</p>`)}
const views={dashboard,pos:ordersView,orders:ordersView,inventory,team,live,marketing,okr,finance,assistant,settings};
function field(name,label,type='text',extra=''){return `<label>${label}<input name="${name}" type="${type}" ${extra}></label>`}
function select(name,label,values,selected=''){return `<label>${label}<select name="${name}">${options(values,selected)}</select></label>`}
function openDialog(title,body,large=false){const d=$('#dialog');if(d.open)d.close();d.className=large?'large':'';d.innerHTML=`<div class="dialoghead"><h2 id="dialog-title">${title}</h2>${button(icon('close'),'close','','iconbutton')}</div>${body}`;d.showModal()}
function form(title,desc,fields,handler,submit='Simpan'){submitOperation=crypto.randomUUID();formHandler=handler;openDialog(title,`<p class="muted">${desc}</p><form id="actionform"><div class="formgrid">${fields}</div><div class="error" role="alert"></div><div class="formactions">${button('Batal','close')}<button class="primary" type="submit">${submit}</button></div></form>`)}
async function sendAction(action,payload,operation=submitOperation){if(preview){openSetup();return}return api('action/'+action,{...payload,operationId:operation||crypto.randomUUID()})}
function requireActive(){if(preview){openSetup();return false}return true}
function openSetup(){form('Aktifkan workspace Albina','Buat password owner. Akun Upi, Feby, Tantri dan Bowo diaktifkan owner setelah masuk.',`<div class="full">${field('password','Password owner (minimal 10 karakter)','password','required minlength="10" maxlength="200" autocomplete="new-password"')}${field('confirm','Ulangi password','password','required minlength="10" autocomplete="new-password"')}<label class="check"><input name="demo" type="checkbox" checked> Gunakan katalog contoh untuk mencoba alur. Matikan untuk mulai dengan katalog kosong.</label></div>`,async(f)=>{if(f.password!==f.confirm)throw new Error('Password konfirmasi tidak sama.');await api('setup',{password:f.password,demo:$('#actionform [name=demo]').checked});await api('login',{id:'owner',password:f.password});return {message:'Workspace aktif. Selamat datang, Owner.'}},'Aktifkan & masuk')}
function saleForm(){return `<p class="muted">Selalu lunas dan langsung diserahkan. Transaksi mengurangi stok lokal; BigSeller perlu diverifikasi terpisah.</p><form id="saleform"><div class="checkout"><div><div class="search">${icon('search')}<input id="catalog-search" placeholder="Cari produk atau SKU…" aria-label="Cari produk kasir"></div><div id="catalog-results" style="margin-top:12px"></div><div id="cart"></div></div><div class="checkoutaside">${select('channel','Asal penjualan',['Toko langsung','WhatsApp','Reseller'])}${field('customer','Pembeli (opsional)','text','maxlength="100"')}${select('method','Metode pembayaran',['Tunai','Transfer bank','QRIS'])}${field('reference','Referensi transfer / QRIS','text','maxlength="150"')}${field('tendered','Uang diterima (Rp)','number','min="1" step="1" required value="0" data-auto="yes"')}${owner()?field('reason','Alasan jika harga berubah / diskon','text','maxlength="500"'):''}<div class="total"><span>Total</span><strong id="cart-total">${rp(0)}</strong></div><div id="change" class="muted"></div><div class="error" role="alert"></div><button class="primary" type="submit">Simpan penjualan & kurangi stok</button><small>Stok diperiksa ulang saat menyimpan. Jika salah satu SKU tidak cukup, seluruh transaksi ditolak.</small></div></div></form>`}
function offlineSales(){return operational()?`<section id="offline-sales" class="card offline-sales" tabindex="-1" aria-labelledby="offline-sales-title"><p class="eyebrow">TOOLS TAMBAHAN</p><h2 id="offline-sales-title">Penjualan offline</h2><p class="muted">Catat transaksi toko, WhatsApp, atau reseller saat diperlukan.</p>${preview?button('Aktifkan workspace untuk mencatat','setup'):saleForm()}</section>`:''}
function initSale(){cart=[];$('#saleform').dataset.operation=crypto.randomUUID();catalog('');drawCart()}
async function submitSale(f,operation){if(!requireActive())return;captureCart();if(!cart.length)throw new Error('Pilih minimal satu produk.');return sendAction('sale',{lines:cart.map(({id,qty,price,discount})=>({id,qty,price,discount})),mode:'direct',channel:f.channel,customer:f.customer,method:f.method,reference:f.reference||'',tendered:Number(f.tendered),reason:f.reason||''},operation)}
function openSale(){if(!requireActive())return;if(page!=='dashboard'&&page!=='pos'){location.hash='pos';return}$('#offline-sales').scrollIntoView({block:'start'});$('#catalog-search').focus({preventScroll:true})}
function catalog(query){$('#catalog-results').innerHTML=S.products.filter(p=>(p.name+p.sku+p.variant).toLowerCase().includes(query.toLowerCase())).slice(0,5).map(p=>`<button type="button" class="catalogresult" data-action="cart-add" data-id="${p.id}"><span>${esc(p.name)}<small>${esc(p.variant)} · ${esc(p.sku)}</small></span><span class="number">${rp(p.price)}<small>${avail(p)} pcs tersedia</small></span></button>`).join('')||'<p class="muted">Produk tidak ditemukan.</p>'}
function captureCart(){for(const l of cart){const q=$(`[name="q-${l.id}"]`);if(q){l.qty=Number(q.value);l.price=Number($(`[name="p-${l.id}"]`).value);l.discount=Number($(`[name="d-${l.id}"]`).value)}}}
function drawCart(){const e=$('#cart');e.innerHTML=cart.length?cart.map(l=>`<article class="cartline"><div class="cartlinehead"><div><strong>${esc(l.name)}</strong><small>${esc(l.variant)}</small></div>${button(icon('close'),'cart-remove',l.id)}</div><div class="cartinputs">${field('q-'+l.id,'Jumlah','number',`value="${l.qty}" min="1" step="1" required`)}${field('p-'+l.id,'Harga / unit','number',`value="${l.price}" min="1" step="1" required ${owner()?'':'readonly'}`)}${field('d-'+l.id,'Diskon nominal','number',`value="${l.discount}" min="0" step="1" required ${owner()?'':'readonly'}`)}</div><div class="subtotal" id="subtotal-${l.id}"></div></article>`).join(''):empty('Keranjang masih kosong','Pilih SKU dan varian dari daftar di atas.');calcCart()}
function calcCart(){captureCart();const total=cart.reduce((a,l)=>a+l.qty*l.price-l.discount,0);$('#cart-total').textContent=rp(total);for(const l of cart)$('[id="subtotal-'+l.id+'"]').textContent=rp(l.qty*l.price-l.discount);const t=$('[name=tendered]');if(t.dataset.auto==='yes')t.value=Math.max(0,total);const method=$('[name=method]').value;const ref=$('[name=reference]');ref.required=method!=='Tunai';$('#change').textContent=method==='Tunai'?'Kembalian: '+rp(Math.max(0,Number(t.value)-total)):'Non-tunai wajib tepat sesuai total.'}
function stockDetail(id){const p=S.products.find(p=>p.id===id);openDialog(esc(p.name),`<p class="muted">${esc(p.variant)} · ${esc(p.sku)}</p>${[['Fisik',p.stock],['Karantina',p.quarantine],['Terpesan',p.reserved],['Tersedia',avail(p)]].map(([l,n])=>`<div class="kv"><span>${l}</span><strong class="number">${n} pcs</strong></div>`).join('')}<div class="note">Saldo lokal. Acuan tetap BigSeller; perubahan belum dikirim otomatis.</div><div class="formactions">${button('Barang masuk','receive',id,'primary')}${button('Koreksi opname','adjust',id)}</div>`)}
function orderDetail(id){const o=S.orders.find(o=>o.id===id);openDialog(esc(o.id),`<p class="muted">${date(o.created)} · ${esc(who(o.actor))}</p><div class="receipt"><h3>Albina Shop</h3><p>${esc(o.customer||'Pembeli umum')} · ${esc(o.channel)}</p><div class="tablewrap"><table><thead><tr><th>BARANG</th><th>QTY</th><th>NILAI</th></tr></thead><tbody>${o.lines.map(l=>`<tr><td>${esc(l.name)}<div>${esc(l.variant)}</div></td><td>${l.qty}${l.returned?'<div>Retur: '+l.returned+'</div>':''}</td><td>${rp(l.net)}</td></tr>`).join('')}</tbody></table></div><div class="kv"><strong>Total</strong><strong>${rp(o.total)}</strong></div><div class="kv"><span>Pembayaran</span><span>${rp(o.paid)} · ${esc(o.method)}</span></div><div class="kv"><span>Kembalian</span><span>${rp(Math.max(0,o.tendered-o.paid))}</span></div><p>${esc(o.status)}</p></div><p class="muted">Hak refund ${rp(o.refundable)} · sudah dicatat ${rp(o.refunded)}. Status ini tidak mengirim uang otomatis.</p><div class="formactions">${button('Cetak bukti','print',id)}${o.status==='Diserahkan'?button('Catat retur','return',id):''}${o.refundable>o.refunded?button('Catat refund','refund',id,'danger'):''}</div>`,true)}
function openAction(action,id){if(!requireActive())return;const p=S.products.find(p=>p.id===id),o=S.orders.find(o=>o.id===id);const num=f=>Object.fromEntries(Object.entries(f).map(([k,v])=>[k,['qty','stock','quarantine','price','cost','amount','budget','views','orders_count','revenue','tendered'].includes(k)?(v===''&&k==='cost'?null:Number(v)):v]));const reason=field('reason','Alasan / referensi','text','required maxlength="500"');let title='',desc='',fields='',fn;
if(action==='product'){title='Tambah produk / SKU';desc='Gunakan SKU yang sama dengan BigSeller. Saldo awal harus dicocokkan dengan fisik.';fields=field('sku','SKU','text','required maxlength="60"')+field('name','Nama produk','text','required maxlength="150"')+field('variant','Ukuran / warna')+field('price','Harga jual (Rp)','number','required min="1" step="1"')+field('stock','Saldo awal fisik','number','required min="0" max="100000" step="1" value="0"')+(owner()?field('cost','HPP (opsional)','number','min="0" step="1"'):'')}
if(action==='receive'){title='Catat barang masuk';desc=p.name+' · saldo saat ini '+p.stock+' pcs';fields=field('qty','Jumlah masuk','number','required min="1" step="1"')+reason;fn=f=>({...num(f),id,version:p.version})}
if(action==='adjust'){title='Koreksi hasil opname';desc='Owner menyetujui koreksi. BigSeller tetap perlu diperbarui terpisah.';fields=field('stock','Fisik hasil hitung','number',`required min="0" step="1" value="${p.stock}"`)+field('quarantine','Karantina','number',`required min="0" step="1" value="${p.quarantine}"`)+`<div class="full">${reason}</div>`;fn=f=>({...num(f),id,version:p.version})}
if(action==='return'){title='Penerimaan retur';desc='Barang harus sudah diterima dan diperiksa. Admin mengajukan persetujuan owner.';fields=select('product','Produk',o.lines.map(l=>[l.id,l.name+' · sisa '+(l.qty-l.returned)]))+field('qty','Jumlah','number','required min="1" step="1"')+select('condition','Kondisi',['Layak jual','Rusak'])+reason;fn=f=>({...num(f),id,version:o.version})}
if(action==='refund'){title='Catat refund yang sudah dilakukan';desc='Ini catatan manual, tidak mengeksekusi transfer. Owner menyetujui nominal.';fields=field('amount','Nilai refund','number',`required min="1" max="${o.refundable-o.refunded}" step="1"`)+reason;fn=f=>({...num(f),id,version:o.version})}
if(action==='task'){title='Tugas baru';desc='Satu tugas memiliki satu PIC utama.';fields=field('title','Nama tugas','text','required maxlength="180"')+select('assignee','PIC',S.users.map(u=>[u.id,u.name]))+field('due','Tenggat','date')}
if(action==='live'){title='Jadwalkan live';desc='Pilih Feby, Tantri atau Bowo. Produk sesi tidak membuat reservasi.';fields=field('title','Nama sesi','text','required')+select('host','Host',S.users.filter(u=>u.role==='host').map(u=>[u.id,u.name]))+field('start','Mulai (WIB)','datetime-local','required')+field('end','Selesai (WIB)','datetime-local','required')+`<div class="full">${field('products','SKU / produk yang disiapkan')}</div>`;fn=f=>({...f,start:f.start+':00+07:00',end:f.end+':00+07:00'})}
if(action==='live-result'){title='Catat hasil sesi';desc='Hasil manual, bukan atribusi order otomatis.';fields=field('views','Views','number','required min="0" step="1"')+field('orders_count','Jumlah order','number','required min="0" step="1"')+field('revenue','Penjualan sesi (Rp)','number','required min="0" step="1"');fn=f=>({...num(f),id})}
if(action==='campaign'){title='Campaign baru';desc='Anggaran dan biaya aktual terpisah. ROAS menunggu sumber atribusi.';fields=field('title','Nama campaign','text','required')+select('channel','Channel',['Shopee','Instagram','TikTok','WhatsApp'])+field('budget','Anggaran (Rp)','number','required min="0" step="1" value="0"')+field('cost','Biaya aktual (Rp)','number','required min="0" step="1" value="0"')}
if(action==='expense'){title='Catat pengeluaran';desc='Catatan pengeluaran lokal owner.';fields=field('title','Keterangan','text','required')+field('amount','Nominal (Rp)','number','required min="1" step="1"')+select('category','Kategori',['Operasional','Kemasan','Transportasi','Lainnya'])}
if(action==='baseline'){title='Tetapkan baseline penjualan';desc='Target tetap bulan pertama 3× dan bulan ketiga 5× baseline yang sama.';fields=field('amount','Baseline (Rp)','number','required min="1" step="1"')+field('start','Mulai pengukuran','date','required')+`<div class="full">${field('scope','Cakupan dan periode baseline','text','required placeholder="Contoh: Penjualan dibayar Shopee per 30 hari, periode…"')}</div>`}
if(action==='password'){title='Atur password '+esc(who(id));desc='Password baru minimal 10 karakter. Sesi akun tersebut akan diakhiri.';fields=`<div class="full">${field('password','Password baru','password','required minlength="10" maxlength="200" autocomplete="new-password"')}</div>`;fn=f=>({...f,id});action='user-password'}
if(action==='sync-confirm'){title='Verifikasi pembaruan BigSeller';desc='Isi hanya setelah mutasi terkait benar-benar diperbarui dan diperiksa di BigSeller.';fields=`<div class="full">${field('evidence','Referensi dokumen / bukti pengecekan','text','required maxlength="500"')}</div>`;fn=f=>({...f,id})}
if(!title)return;form(title,desc,fields,f=>sendAction(action,fn?fn(f):num(f)))}
function exportCSV(rows,name){const csv='\uFEFF'+rows.map(r=>r.map(x=>'"'+String(x??'').replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();URL.revokeObjectURL(url)}
document.addEventListener('submit',async e=>{if(!['actionform','saleform'].includes(e.target.id))return;e.preventDefault();const f=e.target,b=f.querySelector('button[type=submit]'),err=f.querySelector('.error');if(b.disabled)return;b.disabled=true;err.classList.remove('show');try{const values=Object.fromEntries(new FormData(f));const result=await (f.id==='saleform'?submitSale(values,f.dataset.operation):formHandler(values));$('#dialog').close();await refresh();toast(result?.message||'Tersimpan.')}catch(error){err.textContent=error.message;err.classList.add('show');if(error.status===401){$('#dialog').close();login()}}finally{b.disabled=false}});
document.addEventListener('input',e=>{if(e.target.id==='product-search')$$('[data-search]').forEach(row=>row.hidden=!row.dataset.search.includes(e.target.value.toLowerCase()));if(e.target.id==='catalog-search')catalog(e.target.value);if(e.target.name==='tendered'){e.target.dataset.auto='no';calcCart()}else if(/^[qpd]-/.test(e.target.name||''))calcCart()});
document.addEventListener('change',e=>{if(e.target.id==='range'){range=e.target.value;render()}if(e.target.id==='channel'){channel=e.target.value;render()}if(e.target.name==='method'&&$('#cart-total'))calcCart()});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const {action,id}=b.dataset;try{if(action==='close')return $('#dialog').close();if(action==='menu')return $('.sidebar').classList.toggle('open');if(action==='setup')return openSetup();if(action==='reload')return boot();if(action==='refresh')return preview?render():refresh();if(action==='go-assistant'){location.hash='assistant';return}if(action==='sale')return openSale();if(action==='cart-add'){captureCart();const p=S.products.find(x=>x.id===id),l=cart.find(x=>x.id===id);if(l)l.qty++;else cart.push({...p,qty:1,discount:0});drawCart();return}if(action==='cart-remove'){captureCart();cart=cart.filter(l=>l.id!==id);drawCart();return}if(action==='stock-detail')return stockDetail(id);if(action==='order')return orderDetail(id);if(action==='print')return window.print();if(action==='logout'){await api('logout',{});login();return}if(action==='task-toggle'){if(!requireActive())return;const t=S.tasks.find(t=>t.id===id);await sendAction('task-status',{id,status:t.status==='Selesai'?'Belum mulai':'Selesai'},crypto.randomUUID());await refresh();return}if(['approve','reject'].includes(action)){if(!requireActive())return;b.disabled=true;await sendAction('approve',{id,accept:action==='approve'},crypto.randomUUID());await refresh();toast('Pengajuan diproses.');return}if(action==='export-orders'){exportCSV([['ID','Waktu','Petugas','Channel','Pembeli','Total','Lunas','Refund','Status'],...filtered().map(o=>[o.id,o.created,who(o.actor),o.channel,o.customer,o.total,o.paid,o.refunded,o.status])],'albina-penjualan-offline.csv');return}if(action==='export-sync'){exportCSV([['ID mutasi','Waktu','SKU','Jenis','Perubahan fisik','Referensi','Alasan'],...S.movements.map(m=>[m.id,m.created,m.sku,m.kind,m.delta,m.reference,m.reason])],'albina-mutasi-untuk-rekonsiliasi-bigseller.csv');return}if(action==='connect-bigseller'){if(!requireActive())return;form('Hubungkan BigSeller MCP','Masukkan kredensial yang diberikan BigSeller. Key hanya dikirim ke endpoint resmi BigSeller dan disimpan terenkripsi pada komputer ini setelah verifikasi.',field('appId','APP ID','text','required autocomplete="off"')+field('appKey','APP KEY','password','required autocomplete="off"'),f=>sendAction('connect-bigseller',f),'Verifikasi koneksi');return}openAction(action,id)}catch(err){toast(err.message)}finally{b.disabled=false}});
function mountChat(){
 const root=$('#assistant-root');if(!S){root.innerHTML='';return}
 if(chatUser!==S.user.id){chatUser=S.user.id;chatMessages=[];chatOpen=false}
 root.innerHTML=`<button type="button" id="chat-launcher" aria-label="Buka chat Albina Assistant" aria-expanded="${chatOpen}" aria-controls="chat-panel">${icon('spark')}<span>Albina Assistant</span><span class="chat-presence"></span></button><section id="chat-panel" class="${chatOpen?'':'hide'}" aria-labelledby="chat-title"><header class="chat-header"><div class="chat-avatar">${icon('spark')}</div><div><h2 id="chat-title">Albina Assistant</h2><span>Asisten bisnis · mode lokal</span></div><button type="button" id="chat-close" aria-label="Tutup chat">${icon('close')}</button></header><div class="chat-notice">${preview?'Pratinjau · ':'Data lokal sesuai akses akun · '}Model AI generatif belum terhubung.</div><div id="chat-messages" role="log" aria-live="polite" aria-relevant="additions"><div class="chat-message assistant">Halo, ${esc(S.user.name)}! Saya bantu cek stok, penjualan lokal, tugas tim, dan target Albina. Mau mulai dari mana?</div>${chatMessages.map(m=>`<div class="chat-message ${m.role}">${esc(m.text)}</div>`).join('')}${chatBusy?'<div class="chat-message assistant typing">Sedang memeriksa data…</div>':''}</div><div class="chat-suggestions">${['Stok mana yang menipis?','Apa tugas saya?','Target penjualan kita?'].map(q=>`<button type="button" data-chat-question="${esc(q)}">${q}</button>`).join('')}</div><form id="chat-form"><label class="sr-only" for="chat-input">Pesan untuk Albina Assistant</label><textarea id="chat-input" name="question" rows="1" maxlength="500" placeholder="Tulis pesan untuk Albina…" required ${chatBusy?'disabled':''}></textarea><button type="submit" aria-label="Kirim pesan" ${chatBusy?'disabled':''}>${icon('arrow')}</button></form><div class="chat-footnote">Tidak mengubah stok, harga, atau uang lewat chat.</div></section>`;
 const list=$('#chat-messages');list.scrollTop=list.scrollHeight;
}
function previewChat(question){const q=question.toLowerCase();if(/stok|barang|produk|sku/.test(q)){const low=S.products.filter(p=>avail(p)<=p.threshold);return `${low.length} SKU contoh perlu perhatian:\n${low.map(p=>`• ${p.name} · ${p.variant}: ${avail(p)} pcs.`).join('\n')}\n\nIni pratinjau katalog contoh. Aktifkan workspace untuk membaca database lokal.`}if(/tugas|host|tim|live/.test(q))return 'Tim Albina: Owner, Admin Upi, Host Feby, Host Tantri, Host Bowo.\n\nAktifkan workspace untuk membaca tugas yang ditugaskan ke akunmu.';if(/target|okr/.test(q))return 'Target tetap: bulan pertama 3× baseline dan bulan ketiga 5× baseline yang sama. Baseline nominal dan tanggal mulai belum divalidasi.';if(/omzet|penjualan|uang|margin|laba/.test(q))return 'Belum ada transaksi aktual pada pratinjau. Setelah workspace diaktifkan, saya dapat membaca ringkasan penjualan offline sesuai akses akun. Total channel BigSeller belum terhubung.';return 'Halo! Saya bisa membantu cek stok menipis, tugas tim dan target 3×/5×. Saat ini saya dalam mode lokal berbasis aturan, belum AI generatif. Data percobaan bukan laporan aktual toko.'}
async function sendChat(question){question=question.trim();if(!question||chatBusy)return;chatMessages.push({role:'user',text:question});chatBusy=true;mountChat();try{const reply=preview?{reply:previewChat(question)}:await api('assistant',{question});chatMessages.push({role:'assistant',text:reply.reply})}catch(e){chatMessages.push({role:'assistant',text:e.message})}finally{chatBusy=false;if(chatMessages.length>30)chatMessages=chatMessages.slice(-30);mountChat();if(chatOpen)$('#chat-input').focus()}}
document.addEventListener('click',e=>{if(e.target.closest('#chat-launcher')){chatOpen=!chatOpen;mountChat();if(chatOpen)$('#chat-input').focus()}if(e.target.closest('#chat-close')){chatOpen=false;mountChat();$('#chat-launcher').focus()}const suggestion=e.target.closest('[data-chat-question]');if(suggestion)sendChat(suggestion.dataset.chatQuestion)});
document.addEventListener('submit',e=>{if(e.target.id==='chat-form'){e.preventDefault();sendChat($('#chat-input').value)}});
document.addEventListener('keydown',e=>{if(e.target.id==='chat-input'&&e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();sendChat(e.target.value)}if(e.key==='Escape'&&chatOpen&&!$('#dialog').open){chatOpen=false;mountChat();$('#chat-launcher').focus()}});
// The observer only mounts when the main shell changes, keeping chat state across navigation.
new MutationObserver(()=>{if(!S){$('#assistant-root').innerHTML='';chatMessages=[];chatUser=''}else mountChat()}).observe($('#app'),{childList:true});
window.addEventListener('hashchange',()=>{if(S)render()});boot();
